Here is a production-ready, idiomatic Terraform module that fulfills your requirements and aligns with the canonical specification. It is structured for reuse, supports `dev`/`prod` via `tfvars`, and enforces least-privilege and security best practices.

### 📁 Module Structure
```
modules/app-infra/
  ├── main.tf
  ├── variables.tf
  ├── outputs.tf
  └── versions.tf
environments/
  ├── dev/
  │   ├── main.tf
  │   └── dev.tfvars
  └── prod/
      ├── main.tf
      └── prod.tfvars
```

---

### 🧱 `modules/app-infra/main.tf`
```hcl
# S3 Bucket
resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name
  tags   = local.common_tags
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = var.s3_encryption_algorithm
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Optional: Prod cross-region replication
resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.enable_s3_replication ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = var.s3_replication_role_arn

  rule {
    status = "Enabled"
    destination {
      bucket        = var.s3_replication_destination_bucket_arn
      storage_class = "STANDARD"
    }
    filter {}
  }
}

# RDS PostgreSQL
resource "aws_db_instance" "this" {
  identifier                = "${var.environment}-app-db"
  engine                    = "postgres"
  engine_version            = var.db_engine_version
  instance_class            = var.db_instance_class
  allocated_storage         = var.db_allocated_storage
  storage_encrypted         = var.db_storage_encrypted
  multi_az                  = var.db_multi_az
  db_name                   = var.db_name
  username                  = var.db_username
  password                  = var.db_password
  skip_final_snapshot       = true
  deletion_protection       = true
  publicly_accessible       = false
  backup_retention_period   = var.db_backup_retention_period
  db_subnet_group_name      = var.db_subnet_group_name
  vpc_security_group_ids    = var.db_security_group_ids
  tags                      = local.common_tags
}

# IAM Service Role
resource "aws_iam_role" "this" {
  name               = "${var.environment}-app-service-role"
  assume_role_policy = var.assume_role_policy
  tags               = local.common_tags
}

resource "aws_iam_role_policy" "this" {
  name = "${var.environment}-app-service-policy"
  role = aws_iam_role.this.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3Operations"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/*"
        ]
      },
      {
        Sid    = "AllowRDSConnect"
        Effect = "Allow"
        Action = ["rds-db:connect"]
        Resource = aws_db_instance.this.arn
      }
    ]
  })
}

locals {
  common_tags = merge(var.common_tags, {
    Environment = var.environment
    ManagedBy   = "terraform"
  })
}
```

