### 📦 `modules/app-infra/variables.tf`
```hcl
variable "environment" {
  description = "Environment identifier (e.g., dev, prod)"
  type        = string
}

variable "bucket_name" {
  description = "Unique S3 bucket name"
  type        = string
}

variable "s3_encryption_algorithm" {
  description = "S3 SSE algorithm: AES256 or aws:kms"
  type        = string
  default     = "AES256"
}

variable "enable_s3_replication" {
  description = "Enable cross-region replication (prod only)"
  type        = bool
  default     = false
}

variable "s3_replication_role_arn" {
  description = "IAM role ARN for S3 replication"
  type        = string
  default     = null
}

variable "s3_replication_destination_bucket_arn" {
  description = "ARN of destination bucket for replication"
  type        = string
  default     = null
}

variable "db_engine_version" {
  description = "PostgreSQL version"
  type        = string
  default     = "15.4"
}

variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "db_allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "db_storage_encrypted" {
  description = "Enable RDS storage encryption"
  type        = bool
  default     = true
}

variable "db_multi_az" {
  description = "Enable multi-AZ deployment"
  type        = bool
  default     = false
}

variable "db_name" {
  description = "Database name"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "RDS master username"
  type        = string
  sensitive   = true
}

variable "db_password" {
  description = "RDS master password. Inject via TF_VAR_ or SOPS/Secrets Manager."
  type        = string
  sensitive   = true
}

variable "db_backup_retention_period" {
  description = "Backup retention in days (min 7)"
  type        = number
  default     = 7
}

variable "db_subnet_group_name" {
  description = "DB subnet group name"
  type        = string
}

variable "db_security_group_ids" {
  description = "Security group IDs for RDS"
  type        = list(string)
}

variable "assume_role_policy" {
  description = "JSON trust policy for the IAM role"
  type        = string
}

variable "common_tags" {
  description = "Baseline tags for all resources"
  type        = map(string)
  default     = {}
}
```

---

### 📤 `modules/app-infra/outputs.tf`
```hcl
output "s3_bucket_arn" {
  description = "ARN of the S3 bucket"
  value       = aws_s3_bucket.this.arn
}

output "s3_bucket_name" {
  description = "Name of the S3 bucket"
  value       = aws_s3_bucket.this.id
}

output "rds_endpoint" {
  description = "Primary RDS endpoint"
  value       = aws_db_instance.this.endpoint
}

output "rds_arn" {
  description = "ARN of the RDS instance"
  value       = aws_db_instance.this.arn
}

output "iam_role_arn" {
  description = "ARN of the IAM service role"
  value       = aws_iam_role.this.arn
}
```

